package net.civeira.phylax.feature.observe.observedprobe.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbeLastStatusOptions;

class LastStatusVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property last status of observed probe ")
  void test_last_status_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> LastStatusVO.tryFrom("_UP_"));
    Assertions.assertEquals(ObservedProbeLastStatusOptions.UP,
        LastStatusVO.tryFrom("UP").getLastStatus().orElse(null));
    Assertions.assertFalse(LastStatusVO.nullValue().getLastStatus().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(LastStatusVO.tryFrom(null).getLastStatus().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(ObservedProbeLastStatusOptions.UP,
        LastStatusVO.from(ObservedProbeLastStatusOptions.UP).getLastStatus().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> LastStatusVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedProbeLastStatusOptions.UP + "]",
        LastStatusVO.from(ObservedProbeLastStatusOptions.UP).toString());
  }
}
